    const existHud = $$('#type-hud'); if(existHud) existHud.remove();
    const existKb = $$('#type-kb'); if(existKb) existKb.remove();
    const hud = document.createElement('div'); hud.className='game-hud'; hud.id='type-hud'; hud.style.marginBottom='8px';
    hud.innerHTML=`<span class="game-stat">📝 <span class="game-stat-val" id="type-words">0/${typeGoal}</span></span><span class="game-stat">🏆 Best <span class="game-stat-val" id="type-best">0</span> WPM</span>`;
    typeContainer.parentElement.insertBefore(hud, typeContainer);
