    _solRoundRect(ctx, r.x, r.y, r.w, r.h, 6); ctx.fill();
    ctx.strokeStyle = '#aaa'; ctx.lineWidth = 1;
    _solRoundRect(ctx, r.x, r.y, r.w, r.h, 6); ctx.stroke();
    ctx.fillStyle = _solRed(card) ? '#cc2222' : '#111';
    const sz = Math.min(r.w * 0.28, r.h * 0.22);
    ctx.font = `bold ${sz}px monospace`;
    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
