    lifeArea.appendChild(hud);
    const sizeRow=document.createElement('div');sizeRow.style.cssText='display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin:4px 0 10px;';
    [3,4,5,6,7].forEach(n=>{const b=document.createElement('button');b.className='sdk-btn'+(n===nDisks?' active':'');b.style.cssText='font-size:0.85rem;padding:5px 12px;';b.textContent=n+' disks';b.onclick=()=>{sessionStorage.setItem('hanoi-n',n);initHanoi();};sizeRow.appendChild(b);});
    lifeArea.appendChild(sizeRow);
