        b.style.cssText='font-size:2.6rem;padding:10px 18px;border-radius:14px;border:3px solid #2c3e50;background:#fff;cursor:pointer;box-shadow:0 4px 0 #95a5a6;transition:transform 0.1s;';
        b.textContent=a;
