  function checkMelodyNote(note) {
    if(!melodyState||!melodyState.active) return;
    if(note===melodyState.notes[melodyState.idx]) {
      const els=$$all('#melody-display .melody-note'); els[melodyState.idx].classList.remove('current'); els[melodyState.idx].classList.add('done'); melodyState.idx++;
      melodyState.idx>=melodyState.notes.length ? (melodyState.active=false, showFeedback('🎵 Perfect Melody!','#2ecc71'), addScore(3), setTimeout(()=>renderMusicTab(),2000)) : els[melodyState.idx].classList.add('current');
    }
  }
