  function renderRhythm() {
    const ttl=document.createElement('div'); ttl.className='music-title'; ttl.textContent='🥁 Rhythm Game'; musicContent.appendChild(ttl);
    const info=document.createElement('div'); info.className='music-info'; info.textContent='Tap the dots when they light up!'; musicContent.appendChild(info);
    const namedRhythms=[
      {name:'🎲 Random',pattern:null},
      {name:'🪩 Disco (4-on-floor)',pattern:[1,0,1,0,1,0,1,0]},
      {name:'🎸 We Will Rock You',pattern:[1,1,1,0,1,1,1,0]},
      {name:'🌴 Bossa Nova 3-2',pattern:[1,0,1,0,0,1,0,1]},
      {name:'💃 Cha-Cha-Cha',pattern:[1,0,1,1,0,1,1,0]},
      {name:'🎺 Bo Diddley',pattern:[1,0,1,1,1,0,1,0]},
      {name:'👑 Waltz (3/4)',pattern:[1,0,0,1,0,0]}
    ];
    const chosen=sessionStorage.getItem('rhythm-named')||'🎲 Random';
    const named=namedRhythms.find(r=>r.name===chosen&&r.pattern);
    const pickerRow=document.createElement('div'); pickerRow.style.cssText='display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin:8px 0;';
    namedRhythms.forEach(r=>{const b=document.createElement('button');b.className='sdk-btn'+(r.name===chosen?' active':'');b.style.cssText='font-size:0.78rem;padding:5px 9px;';b.textContent=r.name;b.onclick=()=>{sessionStorage.setItem('rhythm-named',r.name);if(rhythmTimer){clearInterval(rhythmTimer);rhythmTimer=null;}renderMusicTab();};pickerRow.appendChild(b);});
    musicContent.appendChild(pickerRow);
    let pattern;
    if(named){pattern=[...named.pattern];}
    else{const b=currentLevel===1?4:(currentLevel===2?6:8);pattern=Array.from({length:b},()=>Math.random()>0.35);}
    const beats=pattern.length;
    const area=document.createElement('div'); area.className='rhythm-area'; area.id='rhythm-dots';
    const dots=[]; for(let i=0;i<beats;i++){ const dot=document.createElement('div'); dot.className='rhythm-dot'; dot.textContent=pattern[i]?'🥁':'—'; dots.push(dot); area.appendChild(dot); }
    musicContent.appendChild(area);
    const scoreDisp=document.createElement('div'); scoreDisp.className='music-info'; scoreDisp.id='rhythm-score'; scoreDisp.textContent='Listen first, then tap along!'; musicContent.appendChild(scoreDisp);
    const startBtn=document.createElement('button'); startBtn.className='start-quiz-btn'; startBtn.textContent='▶ Start Beat'; startBtn.style.background='#e94560'; startBtn.style.boxShadow='0 6px 0 #c0392b'; musicContent.appendChild(startBtn);
    let phase='idle',curBeat=0,hits=0; const bpm=currentLevel===1?80:(currentLevel===2?100:120), intv=60000/bpm;
    startBtn.onclick=()=>{ if(phase!=='idle') return; phase='demo'; startBtn.textContent='👂 Listen...'; curBeat=0; hits=0;
      dots.forEach(d=>d.classList.remove('active','hit','miss'));
      rhythmTimer=setInterval(()=>{ dots.forEach(d=>d.classList.remove('active'));
        if(curBeat>=beats){ clearInterval(rhythmTimer); phase='play'; curBeat=0; startBtn.textContent='🎵 Your Turn!'; $$('#rhythm-score').textContent='Now tap when the dots light up!';
          setTimeout(()=>{ rhythmTimer=setInterval(()=>{ dots.forEach(d=>d.classList.remove('active'));
            if(curBeat>=beats){ clearInterval(rhythmTimer); rhythmTimer=null; phase='idle'; startBtn.textContent='▶ Start Beat';
              const total=pattern.filter(Boolean).length, pct=total>0?Math.round(hits/total*100):100; $$('#rhythm-score').textContent=`Score: ${pct}%`;
              pct>=70?(showFeedback('Great Rhythm! 🥁','#2ecc71'),addScore(2)):showFeedback('Keep Practicing!','#e67e22');
            } else { if(pattern[curBeat]) dots[curBeat].classList.add('active'); curBeat++; }
          },intv);},500); return; }
        if(pattern[curBeat]){ dots[curBeat].classList.add('active'); playDrum(curBeat%2===0?'kick':'snare'); } curBeat++;
      },intv);
    };
    dots.forEach((dot,i)=>{ dot.onclick=()=>{ if(phase!=='play'||dot.classList.contains('hit')) return;
      dot.classList.contains('active')&&pattern[i]?(dot.classList.add('hit'),hits++,playDrum('hihat')):(dot.classList.add('miss'),resetStreak()); }; });
  }
