          grid.parentElement.insertBefore(sum,grid.nextSibling);
          blkLvl = (blkLvl + 1) % levels.length;
          blkOptimal = _bfsOptimal(levels[blkLvl]);
          cmdQueue.length = 0;
          playerPos = [...levels[blkLvl].s];
          visitedCells.clear();
          visitedCells.add(`${playerPos[0]},${playerPos[1]}`);
          blkSteps = 0;
          const le=$$('#blk-lvl'); if(le) le.textContent=blkLvl+1;
          const se=$$('#blk-steps'); if(se) se.textContent='0';
          _blkRefreshTarget();
          setTimeout(() => { document.querySelectorAll('.blk-summary').forEach(n=>n.remove()); info.textContent = `Level ${blkLvl+1}/${levels.length} — Guide 🤖 to ⭐!`; renderGrid(); renderQueue(); }, 2400);
