    function _geoTier(pct){if(pct>=90)return{name:'cartographer',label:'Cartographer',color:'#f1c40f',msg:'Encyclopedic world knowledge.'};if(pct>=75)return{name:'explorer',label:'Explorer',color:'#2ecc71',msg:'Strong global awareness.'};if(pct>=60)return{name:'traveler',label:'Traveler',color:'#70a1ff',msg:'Well-traveled mind.'};if(pct>=40)return{name:'tourist',label:'Tourist',color:'#3498db',msg:'Keep exploring!'};return{name:'starter',label:'Starter',color:'#e67e22',msg:'World awaits.'};}
    const hud = document.createElement('div'); hud.className='game-hud'; hud.id='geo-hud'; hud.style.marginBottom='5px';
    hud.innerHTML=`<span class="game-stat">📊 <span class="game-stat-val" id="geo-progress">0/8</span></span><span class="game-stat">✅ <span class="game-stat-val" id="geo-correct">0</span></span><span class="game-stat">🔥 <span class="game-stat-val" id="geo-streak">0</span></span><span class="game-stat">⭐ Best ${geoBest}</span>`;
