    function startGeo() {
      const lvl = Math.min(currentLevel, 5);
      const allCountries=[].concat(...Object.values(data));pool = allCountries.sort(() => Math.random() - 0.5);
      geoIdx = 0; geoCorrect = 0; geoStreak = 0;
      loadGeoQ();
    }
    function updateHud() {
      const pe=$$('#geo-progress'); if(pe) pe.textContent=`${geoIdx}/${pool.length}`;
      const ce=$$('#geo-correct'); if(ce) ce.textContent=geoCorrect;
      const se=$$('#geo-streak'); if(se) se.textContent=geoStreak;
      const pf=$$('#geo-prog-fill'); if(pf) pf.style.width=Math.round(geoIdx/pool.length*100)+'%';
    }
    function loadGeoQ() {
      updateHud();
      if(geoIdx >= pool.length) {
        flagEl.textContent = '🏆';
        const pct = Math.round(geoCorrect/pool.length*100);
        const wasBest = geoCorrect>geoBest;
        if(wasBest)sessionStorage.setItem('geo-best-L'+currentLevel,geoCorrect);
        const tier=_geoTier(pct);
        promptEl.textContent='';
        choicesEl.innerHTML='';
        document.querySelectorAll('.geo-fact-card,.geo-summary').forEach(n=>n.remove());
        const sum=document.createElement('div');sum.className='geo-summary';
        sum.innerHTML=`<h3>🌍 ${wasBest?'NEW BEST!':'Geography Round Complete'}</h3><div class="tier-tag" style="color:${tier.color}">${tier.label} • ${tier.msg}</div><div class="geo-summary-stats"><div class="geo-summary-stat"><span class="val">${geoCorrect}/${pool.length}</span><span class="lbl">Correct</span></div><div class="geo-summary-stat"><span class="val">${pct}%</span><span class="lbl">Accuracy</span></div><div class="geo-summary-stat"><span class="val">${geoBestStreak}</span><span class="lbl">Best Streak</span></div><div class="geo-summary-stat ${wasBest?'new-best':'best'}"><span class="val">${Math.max(geoCorrect,geoBest)}</span><span class="lbl">All-Time L${currentLevel}</span></div></div>`;
        choicesEl.parentElement.insertBefore(sum,choicesEl);
        if(wasBest)spawnConfetti(window.innerWidth/2,window.innerHeight/2,120);
        else if(tier.name==='cartographer'||tier.name==='explorer')spawnConfetti(window.innerWidth/2,window.innerHeight/3,60);
        showFeedback(`${geoCorrect}/${pool.length} • ${tier.label} 🌍`,wasBest?'#2ecc71':tier.color);
        const retry=document.createElement('button');retry.className='game-btn';retry.textContent='Play Again 🔄';retry.style.marginTop='10px';retry.onclick=startGeo;choicesEl.appendChild(retry);
        return;
      }
      const q = pool[geoIdx];
      flagEl.textContent = q.flag;
      flagEl.style.animation='none'; flagEl.offsetHeight; flagEl.style.animation='bounceIn 0.4s';
      const mode = currentLevel <= 2 ? 0 : (Math.random() < 0.5 ? 1 : 2);
      let question, correct, allOpts;
      if(mode === 0) {
        question = 'Which country is this flag from?';
        correct = q.country;
        allOpts = pool.map(p => p.country);
      } else if(mode === 1) {
        question = `What is the capital of ${q.country}?`;
        correct = q.capital;
        allOpts = pool.map(p => p.capital);
      } else {
        question = `Which continent is ${q.country} in?`;
        correct = q.continent;
        allOpts = [...new Set(pool.map(p => p.continent))];
        if(allOpts.length < 4) allOpts = [...allOpts, 'Antarctica', 'South America', 'Africa', 'Oceania'];
      }
      promptEl.textContent = question;
      let wrongs = allOpts.filter(o => o !== correct).sort(() => Math.random() - 0.5).slice(0, 3);
      const opts = [correct, ...wrongs].sort(() => Math.random() - 0.5);
      choicesEl.innerHTML = '';
      opts.forEach(opt => {
        const btn = document.createElement('button');
        btn.className = 'geo-opt';
        btn.textContent = opt;
        btn.onclick = () => {
          $$all('.geo-opt').forEach(b => { b.style.pointerEvents = 'none'; if(b.textContent===correct) b.style.background='#2ecc71'; });
          const isCorrect = opt===correct;
          if(isCorrect) {
            geoCorrect++; geoStreak++;
            if(geoStreak>geoBestStreak)geoBestStreak=geoStreak;
            const pts = (mode === 0 ? 1 : 2) + (geoStreak >= 5 ? 2 : (geoStreak >= 3 ? 1 : 0));
            addScore(pts);
            if(geoStreak===3||geoStreak===5||geoStreak===8)spawnConfetti(window.innerWidth/2,window.innerHeight/3,geoStreak>=5?80:50);
            showFeedback(geoStreak>=8?`${geoStreak}x! 🔥🔥🔥`:(geoStreak>=5?`${geoStreak}x Streak! 🔥🌍`:(geoStreak>=3?`${geoStreak}x Streak! 🔥`:'Correct! ✨')), '#2ecc71');
          } else {
            btn.style.background = '#e74c3c';
            geoStreak = 0;
            showFeedback(`It's ${correct}`, '#e74c3c');
            resetStreak();
          }
          document.querySelectorAll('.geo-fact-card').forEach(n=>n.remove());
          const card=document.createElement('div');card.className='geo-fact-card'+(isCorrect?'':' miss');
          card.innerHTML=`<div class="country-row"><span class="flag">${q.flag}</span><span>${q.country}</span></div><div class="meta">${q.capital} · ${q.continent}</div><div class="fact">${facts[q.country]||''}</div>`;
          choicesEl.parentElement.insertBefore(card,choicesEl);
          geoIdx++;
          setTimeout(loadGeoQ, 2400);
        };
        choicesEl.appendChild(btn);
      });
    }
