    hud.innerHTML=`<span>📊 <b id="e-prog">1/${queueLen}</b></span><span>🎯 <b style="color:#e67e22" id="e-score">0</b></span><span>🔥 <b style="color:#e74c3c" id="e-streak">0</b></span><span>🏆 Best <b style="color:#f1c40f">${bestStreak}</b></span><span>📈 Life <b style="color:#9b59b6">${lifeCorrect}</b></span>`;
    root.appendChild(hud);
    // Prompt
    const prompt=document.createElement('div');prompt.style.cssText='background:rgba(230,126,34,0.12);border:2px solid #e67e22;padding:18px;border-radius:14px;text-align:center;min-width:260px;max-width:520px;width:90%;display:flex;flex-direction:column;align-items:center;gap:8px;color:var(--text,#ecf0f1);';
    root.appendChild(prompt);
