    input.innerHTML='';for(let n=0;n<=9;n++){const b=document.createElement('button');b.className='spm-key';b.textContent=n===0?'0':n;b.onclick=()=>{if(!spmActive)return;b.classList.add('tap');setTimeout(()=>b.classList.remove('tap'),150);spmBuf+=n;answer.textContent=spmBuf;};input.appendChild(b);}
    const delBtn=document.createElement('button');delBtn.className='spm-key';delBtn.textContent='\u232b';delBtn.onclick=()=>{delBtn.classList.add('tap');setTimeout(()=>delBtn.classList.remove('tap'),150);spmBuf=spmBuf.slice(0,-1);answer.textContent=spmBuf||'_';};input.appendChild(delBtn);
    const goBtn=document.createElement('button');goBtn.className='spm-key';goBtn.textContent='\u2713';goBtn.style.borderColor='#2ecc71';goBtn.style.color='#2ecc71';goBtn.onclick=()=>{goBtn.classList.add('tap');setTimeout(()=>goBtn.classList.remove('tap'),150);submit();};input.appendChild(goBtn);
