    if(window._stpTimer){clearInterval(window._stpTimer);window._stpTimer=null;}
    const allCls=[{n:'RED',h:'#e74c3c'},{n:'BLUE',h:'#3498db'},{n:'GREEN',h:'#2ecc71'},{n:'YELLOW',h:'#f1c40f'},{n:'PURPLE',h:'#9b59b6'},{n:'ORANGE',h:'#e67e22'},{n:'PINK',h:'#ec407a'},{n:'CYAN',h:'#00bcd4'}];
