    const cfg={easy:{count:4,time:30,congruent:0},normal:{count:6,time:30,congruent:0.15},hard:{count:8,time:25,congruent:0.25}};
    const c=cfg[mode]||cfg.normal;
    const cls=allCls.slice(0,c.count);
