      sum.innerHTML=`<h3>\ud83e\udde0 ${wasBest?'NEW BEST!':"Time's up!"}</h3><div class="stp-summary-stats"><div class="stp-summary-stat"><span class="val">${sc}</span><span class="lbl">Correct</span></div><div class="stp-summary-stat"><span class="val">${pct}%</span><span class="lbl">Accuracy</span></div><div class="stp-summary-stat"><span class="val">${avgRT}</span><span class="lbl">Avg ms</span></div><div class="stp-summary-stat"><span class="val">${bestStk}</span><span class="lbl">Best Streak</span></div><div class="stp-summary-stat ${wasBest?'new-best':'best'}"><span class="val">${Math.max(sc,best)}</span><span class="lbl">All-Time</span></div></div>`;
