      const prompt=stpDir==='word'?'Tap the WORD':'Tap the INK COLOR';
      ct.innerHTML=`<div class="stp-word${stk>=3?' streak-fire':''}" id="stp-word" style="color:${ink.h}">${w.n}</div><div class="nmm-msg">${prompt}</div><div class="stp-choices" id="stp-opts"></div>`;
      roundStart=performance.now();
