    function respond(side){if(currentGame!=='taskswitch'||!awaiting)return;awaiting=false;const rt=Date.now()-t0,chosen=side==='L'?valL:valR,ans=rule==='parity'?(num%2?'odd':'even'):(num<5?'low':'high'),ok=chosen===ans;ok?(correct++,streak++,streak%10===0&&(_jzSfx('combo'),spawnConfetti)(window.innerWidth/2,window.innerHeight/3,60),addScore(1),(isSwitch?rtSw:rtRep).push(rt),card.style.animation='sortCorrect 0.3s'):(wrong++,streak=0,resetStreak(),card.style.animation='shake 0.3s');setTimeout(()=>{if(card)card.style.animation='';},320);const c=$$('#ts-c');if(c)c.textContent=correct;const st=$$('#ts-st');if(st)st.textContent=streak;window._tsTimeout=setTimeout(()=>{if(currentGame==='taskswitch')next();},300);}
