          if(isDaily){dailyPending=false;const y=new Date(Date.now()-864e5);const yStr=y.getFullYear()+'-'+String(y.getMonth()+1).padStart(2,'0')+'-'+String(y.getDate()).padStart(2,'0');const last=localStorage.getItem('agm-daily-date');const ns=last===yStr?parseInt(localStorage.getItem('agm-daily-streak')||'0')+1:1;localStorage.setItem('agm-daily-streak',ns);localStorage.setItem('agm-daily-date',_agmToday());const de=$$('#agm-daily');if(de)de.textContent='✅';const ds=$$('#agm-dstk');if(ds)ds.textContent=ns;_jzSfx('win');setTimeout(()=>showFeedback('📅 Daily solved! 🔥 Streak '+ns,'#f1c40f'),600);}
