      let rightmost=0,leftmost=cW;
      enemies.forEach(en=>{if(!en.alive)return;rightmost=Math.max(rightmost,en.x);leftmost=Math.min(leftmost,en.x);});
      if(rightmost>cW-20||leftmost<20){eDir=-eDir;enemies.forEach(en=>{if(en.alive)en.y+=8;});}
      const cols=['#e74c3c','#e67e22','#f1c40f','#2ecc71','#3498db','#9b59b6'];
      enemies.forEach(en=>{if(!en.alive)return;en.x+=eDir*eSpeed;ctx.fillStyle=en.hp>1?'#fff':cols[en.r%cols.length];ctx.fillRect(en.x-10,en.y-8,20,16);if(en.hp>1){ctx.fillStyle=cols[en.r%cols.length];ctx.fillRect(en.x-8,en.y-6,16,12);}if(en.y>cH-20){lives=0;}});
