      hud.innerHTML=`<span style="white-space:nowrap">💣 ${MINES-flagCnt}</span> <span style="white-space:nowrap">⏱ <span id="ms-time">${elapsed}</span>s</span> <span style="white-space:nowrap">🚩 ${gameOver?'GAME OVER':'long-press to flag'}</span>${bestStr?' <span style="white-space:nowrap">⭐ '+bestStr+'</span>':''}`;hud.style.cssText='display:flex;flex-wrap:wrap;justify-content:center;gap:6px 12px;';root.appendChild(hud);
      const g=document.createElement('div');g.className='ms-grid';g.style.gridTemplateColumns=`repeat(${COLS},clamp(24px,${Math.floor(70/COLS)}vw,36px))`;
      for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){
        const cell=document.createElement('div');cell.className='ms-cell';
        if(revealed[r][c]){
          cell.classList.add('revealed');
          if(grid[r][c]===-1){cell.classList.add('mine');cell.textContent='💣';}
          else if(grid[r][c]>0){cell.textContent=grid[r][c];cell.dataset.n=grid[r][c];}
        }else if(flagged[r][c]){cell.classList.add('flagged');}
        let longTimer=null;
        cell.addEventListener('pointerdown',e=>{longTimer=setTimeout(()=>{e.preventDefault();if(gameOver||revealed[r][c])return;flagged[r][c]=!flagged[r][c];render();longTimer='done';},400);});
        cell.addEventListener('pointerup',e=>{if(longTimer==='done')return;clearTimeout(longTimer);
          if(gameOver)return;
          if(firstClick){gen(r,c);firstClick=false;startTime=Date.now();timerInt=setInterval(()=>{if(gameOver||currentGame!=='minesweeper'){clearInterval(timerInt);return;}elapsed=Math.floor((Date.now()-startTime)/1000);const te=$$('#ms-time');if(te)te.textContent=elapsed;},1000);reveal(r,c);render();return;}
          if(flagged[r][c])return;
          if(grid[r][c]===-1){gameOver=true;if(timerInt)clearInterval(timerInt);for(let rr=0;rr<ROWS;rr++)for(let cc=0;cc<COLS;cc++)revealed[rr][cc]=true;render();showFeedback('💥 BOOM!','#e74c3c');resetStreak();_jzSfx('hit');_jzShake($$('#minesweeper-game'),8);return;}
          reveal(r,c);if(checkWin()){gameOver=true;if(timerInt)clearInterval(timerInt);const wasBest=!best[diff]||elapsed<best[diff];if(wasBest){best[diff]=elapsed;sessionStorage.setItem('ms-best',JSON.stringify(best));}_jzSfx('win');const tierMap={easy:[10,'Lightning ⚡'],medium:[30,'Sharp 🎯'],hard:[60,'Master 👑']};const tt=tierMap[diff];const t=elapsed<=tt[0]?` · ${tt[1]}`:'';showFeedback(`${wasBest?'🏆 ':''}Cleared in ${elapsed}s!${t}`,wasBest?'#f1c40f':'#2ecc71');addScore(20);if(wasBest)spawnConfetti(window.innerWidth/2,window.innerHeight/2,120);else if(elapsed<=tt[0])spawnConfetti(window.innerWidth/2,window.innerHeight/3,60);}render();
        });
        cell.dataset.r=r;cell.dataset.c=c;
        g.appendChild(cell);
      }
      g.addEventListener('contextmenu',e=>{e.preventDefault();const cell=e.target.closest('.ms-cell');if(!cell)return;const cr=parseInt(cell.dataset.r),cc=parseInt(cell.dataset.c);if(isNaN(cr)||gameOver||revealed[cr][cc])return;flagged[cr][cc]=!flagged[cr][cc];render();});
      root.appendChild(g);
