  function advLose(){const c=advCtx;advSfx('lose');$$('#adv-root').innerHTML=`<div class="adv-end" style="background:linear-gradient(170deg,#1a1a1a,#3a0d0d)"><div style="font-size:3.4rem">💫</div><div style="font-size:1.2rem;font-weight:900;color:#ff8a80;letter-spacing:2px">DEFEATED...</div><div style="color:#9fc6ff;font-size:0.85rem;margin:10px 0">The ${c.foe[1]} was too strong — but heroes never give up!</div><div style="display:flex;gap:10px;justify-content:center;margin-top:14px"><button class="adv-opt" id="adv-retry" style="max-width:200px">⚔️ Try Again</button><button class="adv-opt" id="adv-map" style="max-width:200px">🗺️ Map</button></div></div>`;$$('#adv-retry').onclick=()=>advBattle(c.sub,c.node);$$('#adv-map').onclick=advRenderMap;}
  function advToggle(){if(currentGame==='adventure'){$$('#nav-back').click();return;}if(currentGame)$$('#nav-back').click();advLoad();currentGame='adventure';showView('adventure');advS.hero?advRenderMap():advHeroPick();}
  ACHIEVEMENTS.push({id:'adv-first',ic:'⚔️',name:'First Quest',desc:'Win an Adventure Mode battle',progress(){const c=_intLS('adv-wins');return{cur:Math.min(c,1),target:1,unlocked:c>=1};}},{id:'adv-crit25',ic:'⚡',name:'Crit Master',desc:'Land 25 critical hits in Adventure',progress(){const c=_intLS('adv-crits');return{cur:Math.min(c,25),target:25,unlocked:c>=25};}},{id:'adv-boss5',ic:'👑',name:'Boss Breaker',desc:'Defeat 5 Adventure bosses',progress(){const c=_intLS('adv-bosses');return{cur:Math.min(c,5),target:5,unlocked:c>=5};}},{id:'adv-gear',ic:'🗡️',name:'Geared Up',desc:'Buy gear in the Hero Shop',progress(){let g=-1;try{const s=JSON.parse(localStorage.getItem('adv-state')||'{}');g=Math.max(typeof s.gearW==='number'?s.gearW:-1,typeof s.gearA==='number'?s.gearA:-1);}catch(e){}return{cur:g>=0?1:0,target:1,unlocked:g>=0};}},{id:'adv-realm',ic:'🐉',name:'Realm Saver',desc:'Defeat the Shadow Dragon',progress(){let f=0;try{f=(JSON.parse(localStorage.getItem('adv-state')||'{}').prog||{}).final0||0;}catch(e){}return{cur:f>0?1:0,target:1,unlocked:f>0};}});
  (function(){const b=$$('#adv-btn');if(b)b.onclick=advToggle;try{Object.defineProperty(window,'__advT',{get:()=>{try{return sessionStorage.getItem('adv-test')==='1'?{a:advCur&&advCur.a,lv:advCur&&advCur._lv,foe:advFoeHP,hero:advHeroHP,xp:advS&&advS.xp,prog:advS&&advS.prog,coins:advS&&advS.coins,gearW:advS&&advS.gearW,gearA:advS&&advS.gearA,relics:advS&&advS.relics,hmax:advCtx&&advCtx.hmax,lastHit:advLastHit,ac:advAC?advAC.state:null,sfx:advSfxOn(),daily:advS&&advS.daily,ngp:advS&&!!advS.ngp,enraged:advCtx&&!!advCtx.enraged}:null;}catch(e){return null;}}});}catch(e){}})();
